package com.chronos.education.grade.service;
import com.chronos.education.scheduling.dao.EducationUserBindingRepository; import com.chronos.portal.spi.*; import java.util.*; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
/** 成绩独立门户贡献，避免污染既有 DATA provider。 */
@Component public class GradePortalContributionProvider implements PortalContributionProvider { private final EducationUserBindingRepository bindings; private final GradeCenterService grades; public GradePortalContributionProvider(EducationUserBindingRepository bindings,GradeCenterService grades){this.bindings=bindings;this.grades=grades;} @Override public String providerCode(){return "GRADE";} @Override @Transactional(readOnly=true) public PortalContribution load(String username){List<Map<String,Object>> result=new ArrayList<>();bindings.findByUsernameAndStatusOrderByProfileType(username,"ACTIVE").stream().filter(x->"STUDENT".equals(x.getProfileType())).forEach(x->grades.studentGrades(x.getProfileId()).forEach(g->result.add(Map.of("id",g.getId(),"studentId",g.getStudentId(),"totalScore",g.getTotalScore(),"passed",g.getPassed(),"versionNo",g.getVersionNo()))));return new PortalContribution("GRADE",true,"ok",Map.of("route","/portal/education/grades","grades",result));}}
